states.rawSource:
nui 1
module Panel() {
  group Outer {
    for i in range(min: 0, max: 1, step: 1) {
      if (true) {
        group Inner {
          point Same = coordinate(x: 0, y: 0)
        }
      } else {
        point Same = coordinate(x: 1, y: 1)
      }
    }
  }
}

